// Package gnrt is the small run-time helper package of GoNext. Code
// generated by the gonext transpiler imports it only when a lowering needs
// one of its helpers; it is written in pure Go without cgo.
package gnrt

import "unsafe"

// BoolWord stores a boolean payload in a scalar word of a compact enum.
func BoolWord[B ~bool](b B) uint64 {
	if b {
		return 1
	}
	return 0
}

// Ptr returns the pointer word of a pointer-shaped value (map, channel or
// function) so that it can be stored in an unsafe.Pointer slot of a compact
// enum, where the garbage collector still sees it.
func Ptr[T any](v T) unsafe.Pointer {
	if unsafe.Sizeof(v) != unsafe.Sizeof(uintptr(0)) {
		panic("gnrt: Ptr of a value that is not pointer-shaped")
	}
	return *(*unsafe.Pointer)(unsafe.Pointer(&v))
}

// FromPtr is the inverse of Ptr.
func FromPtr[T any](p unsafe.Pointer) T {
	var v T
	if unsafe.Sizeof(v) != unsafe.Sizeof(uintptr(0)) {
		panic("gnrt: FromPtr of a type that is not pointer-shaped")
	}
	*(*unsafe.Pointer)(unsafe.Pointer(&v)) = p
	return v
}

// NonExhaustive is the panic value of a match that found no arm. It can
// only be reached by enum values that were not built by a constructor, for
// example zero values.
type NonExhaustive struct{ Enum string }

func (e NonExhaustive) Error() string { return "gonext: non-exhaustive match on " + e.Enum }
